insert into practice_generated_content_attempts (
    attempt_id, generated_content_id, attempt_number, attempt_type, status, outcome,
    violation_codes, started_at, completed_at
) values (
    #{attemptId,typeHandler=com.zhangspaghetti.babytalk.practice.generated.internal.UuidTypeHandler},
    #{generatedContentId}, #{attemptNumber}, #{attemptType}, #{status}, #{outcome},
    ARRAY[#{code}]::text[],
    #{startedAt,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler},
    #{completedAt,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler}
)

mapper.update:
update practice_ai_operation_runs
set status = 'completed', outcome = #{outcome},
    completed_at = #{completedAt,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler}
where operation_run_id = #{operationRunId,typeHandler=com.zhangspaghetti.babytalk.practice.generated.internal.UuidTypeHandler}
  and status = 'started'

update practice_ai_provider_calls
set outcome = #{outcome}, provider_trace_id = #{providerTraceId}, latency_ms = #{latencyMs},
    completed_at = #{completedAt,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler}
where provider_call_id = #{providerCallId,typeHandler=com.zhangspaghetti.babytalk.practice.generated.internal.UuidTypeHandler}
  and completed_at is null
